// Recover the EXACT bytes of the request body.
//
// With `rawBody: true` the webhook puts the parsed object in $json.body and the
// original bytes in binary property `data`. Those are not interchangeable:
// re-serialising the parsed object with JSON.stringify() reorders nothing but
// drops the sender's whitespace, so a pretty-printed payload hashes to a
// different digest than the one the sender signed. Verified on 2.34.6 — a body
// sent as `{ "city": "X",  "jobId": "Y" }` (47 bytes) re-serialises to 40.
//
// Buffer is available in the Code sandbox even on Cloud, where `crypto` is not.
const bin = $input.item.binary?.data ?? null;

let raw = null;
if (bin?.data) {
  raw = Buffer.from(bin.data, 'base64').toString('utf8');
} else if (typeof $json.body === 'string') {
  raw = $json.body;
}

return {
  json: {
    raw: raw ?? '',
    rawMissing: raw === null,
    body: $json.body ?? null,
    providedSignature: ($json.headers?.['x-dr-signature'] ?? '').trim(),
  },
};

// Compare the signature the Crypto node computed against the one the caller
// sent, then apply the payload rules. No crypto module is required here — the
// hashing already happened in the Crypto node, which runs outside the sandbox.
function safeEqual(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') return false;
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

const expected = ($json.expectedSignature ?? '').toLowerCase();
const provided = ($json.providedSignature ?? '').toLowerCase();

if ($json.rawMissing) {
  return { json: { ok: false, reason: 'Could not read the raw request body — enable "Raw Body" on the webhook node.' } };
}

if (!safeEqual(expected, provided)) {
  return { json: { ok: false, reason: 'Signature mismatch.' } };
}

const body = $json.body;

// --- Payload rules
const problems = [];
if (!body?.jobId) problems.push('jobId is required.');
if (!body?.city) problems.push('city is required.');
if (body?.customerConsented !== true) problems.push('customerConsented must be true — no post without written homeowner consent.');

const before = body?.photos?.before ?? [];
const after = body?.photos?.after ?? [];
if (after.length === 0) problems.push('At least one "after" photo is required.');

const httpsOnly = [...before, ...after].every((u) => typeof u === 'string' && u.startsWith('https://'));
if (!httpsOnly) problems.push('Photo URLs must be public HTTPS — Instagram fetches them server-side.');

if (problems.length) {
  return { json: { ok: false, reason: problems.join(' ') } };
}

return { json: { ok: true, ...body, before, after, crmBaseUrl: $json.crmBaseUrl } };

// Turn the closeout record into a brief the caption model can work from.
// Deliberately spare: the model is told elsewhere not to invent detail, so
// anything not in the payload must not appear here either.
const j = $json;

const cause = j.damageCause ? `${j.damageCause} damage` : 'storm damage';
const roof = j.roofType ? ` a ${j.roofType} roof` : ' a roof';
const duration = j.crewDays ? ` The crew finished in ${j.crewDays === 1 ? 'a single day' : `${j.crewDays} days`}.` : '';

const brief = [
  `A completed ${cause} replacement in ${j.city}.`,
  `The crew replaced${roof}.${duration}`,
  j.before.length
    ? 'The post shows before and after photos side by side — write copy that points at what changed without narrating the images shot by shot.'
    : 'The post shows the finished roof.',
  'Close by inviting anyone in the area who took damage in the same weather to have their roof looked at.',
].join(' ');

// Before photos first so the carousel reads left to right as a story.
const media = [...j.before.slice(0, 4), ...j.after.slice(0, 6)].map((url) => ({ url, type: 'image' }));

return {
  json: {
    jobId: j.jobId,
    theme: 'job_showcase',
    platforms: ['facebook', 'instagram'],
    scheduledFor: new Date().toISOString(),
    brief,
    targetCity: j.city,
    media,
    crmBaseUrl: j.crmBaseUrl,
  },
};
